ROOT=Path(__file__).parent
ink='#243640'; cream='#fff1d5'; gold='#efbd5b'; red='#cd6554'; blue='#4b8395'; green='#638a6d'
def p(d,f,sw=2): return f'<path d="{d}" fill="{f}" stroke="{ink}" stroke-width="{sw}" stroke-linejoin="round" stroke-linecap="round"/>'
def e(x,y,rx,ry,f): return f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}" fill="{f}"/>'
def rect(x,y,w,h,f,r=2): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{f}" stroke="{ink}" stroke-width="2"/>'
def face(y=47,space=11,mouth=65):
 s=''
 for side,x in [('left',50-space),('right',50+space)]:
  s+=f'<ellipse id="eye-{side}-white" cx="{x}" cy="{y}" rx="5" ry="6" fill="{cream}"/><circle id="eye-{side}-pupil" class="pupil" cx="{x+1}" cy="{y+1}" r="2.5" fill="{ink}"/><circle id="eye-{side}-highlight" cx="{x+2}" cy="{y-1}" r="1.5" fill="white" opacity="0"/><path id="brow-{side}" d="M{x-5} {y-9} Q{x} {y-12} {x+5} {y-9}" fill="none" stroke="{ink}" stroke-width="2" stroke-linecap="round"/>'
 return s,f'<g id="head-bottom"><path id="mouth-closed" d="M44 {mouth-1} Q50 {mouth+3} 57 {mouth-1}" fill="none" stroke="{ink}" stroke-width="2" stroke-linecap="round"/><ellipse id="mouth-open" cx="50" cy="{mouth}" rx="5" ry="3" fill="{ink}" opacity="0"/></g>'
def save(id,name,desc,tags,body,head,y=47,space=11,mouth=65):
 eyes,lips=face(y,space,mouth)
 svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 150" role="img" aria-label="{name}"><title>{name}</title><g id="body">{body}</g><g id="head-top">{head}{eyes}</g>{lips}</svg>'
 d=ROOT/id;d.mkdir(exist_ok=True);(d/'front.svg').write_text(svg);(d/'meta.json').write_text(json.dumps(dict(name=name,description=desc,tags=tags,model='GPT-6 Astra',category='characters'),indent=2)+'\n')
